&lt;li&gt;&lt;span class=&quot;ph-line-height-1_2&quot; data-ph-process-line-height=&quot;true&quot; data-ph-style-attr=&quot;ph-line-height-1_2&quot;&gt;&lt;span class=&quot;darkar&quot;&gt;&lt;span class=&quot;darkar&quot;&gt;&lt;span class=&quot;phw-g-i-70nnOa&quot;&gt;Annual Leave - 25 days per annum plus an additional day of annual leave for each year of service, up to a total of 5 additional days&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;darkar&quot;&gt;&lt;span class=&quot;darkar&quot;&gt;&lt;span class=&quot;phw-g-i-70nnOa&quot;&gt;Additional leave programs to support you and your family&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
